mapper.update:
UPDATE exam_question_answer
SET score = #{score}, annotation = #{annotation}
WHERE exam_id = #{examId} AND question_id = #{questionId}
  AND question_type = #{questionType} AND student_id = #{studentId}

mapper.select:
SELECT * FROM exam_question_answer
WHERE exam_id = #{examId} AND question_id = #{questionId}
  AND question_type = #{questionType} AND student_id = #{studentId}
